"""Exact finite-group checks for the one-place class-number ascent."""
import itertools
import json


def closure(generators, identity, multiply):
    """List the finite monoid generated by the supplied group elements."""
    generators = tuple(generators)
    found = {identity}
    frontier = [identity]
    while frontier:
        a = frontier.pop()
        for b in generators:
            c = multiply(a, b)
            if c not in found:
                frontier.append(c)
                found.add(c)
    return frozenset(found)


def heisenberg(p):
    elements = list(itertools.product(range(p), repeat=3))
    zero = (0, 0, 0)
    def multiply(x, y):
        a, b, c = x
        d, e, f = y
        return ((a+d) % p, (b+e) % p, (c+f+a*e) % p)
    def inverse(x):
        a, b, c = x
        return (-a % p, -b % p, (a*b-c) % p)
    # The kernels of the p+1 projective linear forms on the abelianization.
    forms = [(1,t) for t in range(p)]+[(0,1)]
    maximal = [frozenset(x for x in elements if (u*x[0]+v*x[1])%p==0) for u,v in forms]
    assert len(set(maximal)) == p+1
    assert all(len(row)==p*p for row in maximal)
    cyclic = {closure([g], zero, multiply) for g in elements if g!=zero}
    multiplicities = {}
    for row in cyclic:
        n = sum(row.issubset(large) for large in maximal)
        assert n > 0 and len(row) == p
        multiplicities[n] = multiplicities.get(n, 0)+1
    generator = (1,0,0)
    conjugates = {multiply(multiply(g,generator),inverse(g)) for g in elements}
    normal = closure(conjugates, zero, multiply)
    assert len(normal)==p*p and normal in maximal
    assert len(conjugates)==p
    # A second nonconjugate inertia class projects to an independent direction.
    both = closure([generator,(0,1,0)], zero, multiply)
    assert len(both)==len(elements) and not any(both <= large for large in maximal)
    return dict(prime=p,order=len(elements),cyclic_inertia_candidates=len(cyclic),
                index_p_normal_kernels=len(maximal),containment_multiplicities=multiplicities,
                one_generator_conjugates=len(conjugates),one_normal_closure=len(normal),
                two_independent_inertia_generated=len(both))


def non_p_group():
    els=list(itertools.permutations(range(3)))
    unit=(0,1,2)
    def mul(a,b):
        return tuple(a[b[i]] for i in range(3))
    tau=(1,0,2)
    inv={a:next(x for x in els if mul(a,x)==unit) for a in els}
    conjugates={mul(mul(s,tau),inv[s]) for s in els}
    small=closure([tau],unit,mul)
    full=closure(conjugates,unit,mul)
    assert len(small)==2 and len(full)==6
    return dict(group="S3",inertia=len(small),conjugates=len(conjugates),normal_closure=len(full))


def abelian_sections():
    # A class prime to seven may survive at the same time as the seven-primary part vanishes.
    result=[]
    for order in [1,2,5,7,14,49,50,343]:
        image={7*a%order for a in range(order)}
        quotient=order//len(image)
        assert (quotient==1)==(order%7!=0)
        result.append(dict(order=order,seventh_power_quotient=quotient))
    # Failure of the single-place assumption inside an abelian 7-group.
    v=[(a,b) for a in range(7) for b in range(7)]
    planes=[set(x for x in v if (a*x[0]+b*x[1])%7==0) for a,b in [(1,i) for i in range(7)]+[(0,1)]]
    assert not any({(1,0),(0,1)} <= line for line in planes)
    assert all(any({g}<=line for line in planes) for g in v)
    return dict(power_map_controls=result,two_independent_places_common_index_seven=0)


if __name__=="__main__":
    print(json.dumps({"heisenberg":heisenberg(7),"non_p_group":non_p_group(),
                      "abelian":abelian_sections()},indent=2,sort_keys=True))
